// ── 📐 sondas-mundo · LIBRERÍA: preguntarle al mundo por FORMA, no por celda ──────────────────────
// No hace nada al correr. Se usa desde otro snippet:
//
//     const S = await game.snippet('sondas-mundo');
//     if(S.solido(x, y, z)) …
//
// ────────────────────────────────────────────────────────────────────────────────────────────────
// POR QUÉ EXISTE ESTE FICHERO
//
// «¿Hay materia aquí?» tiene DOS respuestas en este motor y elegir la fácil es un bug con nombre:
//
//   · `mcSolid(x,y,z)` contesta POR CELDA: «¿el id de esta celda es != 0?». Para una antorcha, una
//     flor, una placa de presión o un repetidor eso es `true` en el CUBO ENTERO de 1×1×1, aunque el
//     dibujo ocupe cuatro voxeles. Quien se crea esa respuesta se encuentra el mundo lleno de
//     CAJAS INVISIBLES: el agente choca con el aire que hay encima de una alfombra, el rayo de la
//     palanca se para antes de tocarla, y la sangre se queda flotando alrededor de la antorcha.
//   · La forma de verdad está en `mc._geoFina[id]` = `{bits, fdim}`: el bitset del dibujo a 1/16,
//     que es lo que consulta `mcTerrenoChoca` (app.js) para chocar al JUGADOR. Preguntando aquí,
//     lo que sondees se cuela exactamente por donde se cuela el jugador — que es la definición
//     práctica de «realista» en este mundo.
//
// Esto estaba reimplementado tres veces (agentes en `mundo-autoarranque`, rayo fino en
// `redstone-piezas`, gotas en `herramienta-espada`), cada una encontrada a base de su propio bug.
// Aquí queda una sola vez. Si encuentras una cuarta copia, bórrala y llama a esto.
//
// ⚠️ DOS AVISOS QUE CUESTAN CARO
//
//  1. `mc.structures` se sondea con `mcFineBoxHit._orig`, la versión SIN ENVOLVER. La envuelta por
//     `mundo-autoarranque` incluye las piezas de los agentes articulados (eso es BUG-AG19, y para
//     apuntarles está bien), pero un agente ANDA: lo que se apoye en él se queda flotando en el aire
//     cuando se va. Estas sondas contestan por el mundo QUIETO. Quien quiera agentes tiene
//     `game.esqueletos.enPunto(x,y,z)`, que es la pregunta de al lado y está hecha para eso.
//  2. La rejilla se pregunta con `mcSolidWalk`, no con `mcSolid` — la misma elección que hace
//     `mcTerrenoChoca`. Una hierba atravesable o una placa se ven, se apuntan y se rompen, pero no
//     frenan; si frenasen, cualquier cosa que caiga se posaría sobre una brizna de hierba.
//     ⛔ Y `mcSolid` NO se parchea nunca: lo comparten el mallado, el rayo y romper/poner.

const MC_T = (typeof MC_TILE === 'number') ? MC_TILE : 16;   // 1/16 de bloque, el voxel fino

// El bitset de esa celda, o null si es un cubo macizo normal (o no hay nada fino en este mundo).
function geoFina(bx, by, bz){
  if(typeof mc === 'undefined' || !mc._geoFina || !mc.grid || typeof mcIdx !== 'function') return null;
  if(typeof mcInside === 'function' && !mcInside(bx, by, bz)) return null;
  const g = mc._geoFina[mc.grid[mcIdx(bx, by, bz)]];
  return (g && g.bits) ? g : null;
}

// ¿Materia sólida en este punto, mirando SOLO el terreno (mc.grid)?
function solidoRejilla(x, y, z){
  if(y < 0) return true;                                   // el suelo del mundo, sólido hacia abajo
  const bx = Math.floor(x), by = Math.floor(y), bz = Math.floor(z);
  const rej = (typeof mcSolidWalk === 'function') ? mcSolidWalk
            : (typeof mcSolid === 'function' ? mcSolid : null);
  if(!rej || !rej(bx, by, bz)) return false;
  const g = geoFina(bx, by, bz);
  if(!g) return true;                                      // celda maciza de verdad: el cubo entero
  const d = g.fdim;
  const fx = Math.floor(x*MC_T) - bx*MC_T,
        fy = Math.floor(y*MC_T) - by*MC_T,
        fz = Math.floor(z*MC_T) - bz*MC_T;
  if(fx < 0 || fy < 0 || fz < 0 || fx >= d[0] || fy >= d[1] || fz >= d[2]) return false;
  return !!g.bits[(fy*d[2] + fz)*d[0] + fx];               // el palo de la antorcha, y nada más
}

// ── ÍNDICE GRUESO DE ESTRUCTURAS ────────────────────────────────────────────────────────────────
// Las cajas (AABB, en voxeles finos) de lo que hay estampado, en un array plano de 6 en 6, más la
// caja de todas juntas. Sirve para UNA cosa: no entrar en `mcFineBoxHit` cuando no hace falta.
//
// ⚠️ Por qué hace falta: `mcFineBoxHit` recorre TODAS las estructuras y, para poder descartar una
// por su caja, antes hace `mcStructColl(s)` — un acceso a `mc.structs[s.key]` y tres cadenas de
// propiedades. Con 80 estructuras eso costaba 9,2 µs POR SONDA, y la nieve hace cientos por frame:
// 1,91 ms de los 2,28 que tardaba el paso completo. Aquí es aritmética pura sobre un array plano.
//
// ⚠️ El índice NO contesta nunca que SÍ hay materia: solo dice «ni te molestes». La respuesta buena
// la sigue dando `mcFineBoxHit`, intacta. Por eso, si algo falla o no se ha refrescado, se pregunta
// como siempre: quedarse sin índice es lento, no incorrecto.
//
// ⛔ Y por eso NO se parchea `mcFineBoxHit` para meterle esto dentro: `test_rayo_apuntado.js` la
// extrae VERBATIM por texto y una referencia nueva ahí dentro la revienta con ReferenceError.
let _cajas = null, _gx0 = 0, _gy0 = 0, _gz0 = 0, _gx1 = -1, _gy1 = -1, _gz1 = -1;

// Se llama UNA VEZ POR FRAME, y el que sondea en bucle es quien la llama (`particulas-voxel` al
// empezar su paso). Sin relojes ni caducidades: dentro de un frame el mundo estampado no se mueve,
// y entre frames se rehace — son ~80 iteraciones, lo que costaba UNA sonda de las de antes.
function refrescaEstructuras(){
  if(typeof mc === 'undefined' || !mc.structures || typeof mcStructColl !== 'function'){ _cajas = null; return 0; }
  const c = [];
  _gx0 = _gy0 = _gz0 = Infinity; _gx1 = _gy1 = _gz1 = -Infinity;
  for(const s of mc.structures){
    if(s._isHeldTool) continue;                 // la herramienta en la mano no es mundo quieto
    const g = mcStructColl(s); if(!g) continue;
    const d = g.fdim, E = (s.esc === undefined) ? 1 : s.esc,
          x0 = s.ox*MC_T, y0 = s.oy*MC_T, z0 = s.oz*MC_T,
          x1 = x0 + d[0]*E - 1, y1 = y0 + d[1]*E - 1, z1 = z0 + d[2]*E - 1;
    c.push(x0, y0, z0, x1, y1, z1);
    if(x0 < _gx0) _gx0 = x0; if(y0 < _gy0) _gy0 = y0; if(z0 < _gz0) _gz0 = z0;
    if(x1 > _gx1) _gx1 = x1; if(y1 > _gy1) _gy1 = y1; if(z1 > _gz1) _gz1 = z1;
  }
  _cajas = c;
  return c.length / 6;
}

// ¿Merece la pena preguntar por esta caja fina? `true` sin índice: el que no lo refresca no pierde.
function _puedePillar(fx0, fy0, fz0, fx1, fy1, fz1){
  const c = _cajas; if(!c) return true;
  if(fx1 < _gx0 || fx0 > _gx1 || fy1 < _gy0 || fy0 > _gy1 || fz1 < _gz0 || fz0 > _gz1) return false;
  for(let i = 0; i < c.length; i += 6)
    if(fx1 >= c[i] && fx0 <= c[i+3] && fy1 >= c[i+1] && fy0 <= c[i+4] && fz1 >= c[i+2] && fz0 <= c[i+5])
      return true;
  return false;
}

// ¿Y en mc.structures (las piezas sueltas, las salas, lo estampado)?
function solidoEstructura(x, y, z){
  const caja = (typeof mcFineBoxHit === 'function') ? (mcFineBoxHit._orig || mcFineBoxHit) : null;
  if(!caja) return false;
  const fx = Math.floor(x*MC_T), fy = Math.floor(y*MC_T), fz = Math.floor(z*MC_T);
  if(!_puedePillar(fx, fy, fz, fx, fy, fz)) return false;
  return !!caja(fx, fy, fz, fx, fy, fz);
}

// Las dos preguntas juntas, que es lo que quiere casi todo el mundo.
function solido(x, y, z){
  return solidoRejilla(x, y, z) || solidoEstructura(x, y, z);
}

// ¿En TODA esta caja del mundo no hay absolutamente nada? La fase GRUESA: una sola pregunta por un
// tramo entero, en vez de una por cada punto del tramo.
//
// ⚠️ Existe porque `mcFineBoxHit` recorre `mc.structures` ENTERO en cada llamada — no hay índice
// espacial —, así que lo caro no es la caja, es el número de llamadas. Quien avance rápido (una
// gota de lluvia hace 1,3 bloques por frame) tenía que trocear el paso para no atravesar el suelo
// y pagaba ese bucle una vez por trozo: medidas 22 sondas por gota y frame, todas contestando
// «aire». Preguntando primero por la caja del tramo entero se contesta lo mismo con UNA.
//
// ⚠️ Es CONSERVADORA a propósito, y la asimetría es la clave: `false` («aquí puede haber algo») no
// cuesta más que volver al camino lento, pero un `true` de más sería atravesar una pared. Por eso
// la rejilla se mira POR CELDA, sin afinar la forma: sobre una antorcha contesta `false` aunque el
// tramo pase por el aire de su celda, y ese caso se resuelve, como antes, punto a punto.
function cajaVacia(x0, y0, z0, x1, y1, z1){
  if(y0 < 0 || y1 < 0) return false;                       // el suelo del mundo es sólido
  const bx0 = Math.floor(Math.min(x0, x1)), bx1 = Math.floor(Math.max(x0, x1)),
        by0 = Math.floor(Math.min(y0, y1)), by1 = Math.floor(Math.max(y0, y1)),
        bz0 = Math.floor(Math.min(z0, z1)), bz1 = Math.floor(Math.max(z0, z1));
  // Una caja enorme haría más trabajo aquí que el que ahorra: que conteste el camino lento.
  if((bx1-bx0+1) * (by1-by0+1) * (bz1-bz0+1) > 64) return false;
  const rej = (typeof mcSolidWalk === 'function') ? mcSolidWalk
            : (typeof mcSolid === 'function' ? mcSolid : null);
  if(rej) for(let bx = bx0; bx <= bx1; bx++) for(let by = by0; by <= by1; by++)
    for(let bz = bz0; bz <= bz1; bz++) if(rej(bx, by, bz)) return false;
  const caja = (typeof mcFineBoxHit === 'function') ? (mcFineBoxHit._orig || mcFineBoxHit) : null;
  if(caja){
    const a = Math.floor(Math.min(x0,x1)*MC_T), b = Math.floor(Math.min(y0,y1)*MC_T),
          c = Math.floor(Math.min(z0,z1)*MC_T), d = Math.floor(Math.max(x0,x1)*MC_T),
          e = Math.floor(Math.max(y0,y1)*MC_T), f = Math.floor(Math.max(z0,z1)*MC_T);
    if(_puedePillar(a, b, c, d, e, f) && caja(a, b, c, d, e, f)) return false;
  }
  return true;
}

// La Y de la primera superficie sólida por DEBAJO de este punto (el sitio donde se posaría algo que
// cae ahí), o null si no hay nada en `maxCaida` bloques. Va a paso de voxel fino: no se salta una
// alfombra de un voxel, que es justo lo que se busca al usar estas sondas.
function suelo(x, y, z, maxCaida){
  const n = Math.ceil((maxCaida || 64) * MC_T);
  for(let i = 1; i <= n; i++){
    const yy = y - i / MC_T;
    if(yy < 0) return 0;
    if(solido(x, yy, z)) return Math.floor(yy * MC_T + 1) / MC_T;
  }
  return null;
}

return { solido, solidoRejilla, solidoEstructura, cajaVacia, refrescaEstructuras,
  geoFina, suelo, MC_T,
  info(){ return { geoFinaEnEsteMundo: !!(typeof mc !== 'undefined' && mc._geoFina),
                   sondaEstructuras: (typeof mcFineBoxHit === 'function')
                     ? (mcFineBoxHit._orig ? 'mcFineBoxHit._orig (sin envolver) ✅' : 'mcFineBoxHit (no envuelta)')
                     : 'no hay',
                   rejilla: (typeof mcSolidWalk === 'function') ? 'mcSolidWalk ✅' : 'mcSolid (peor)',
                   indiceEstructuras: _cajas ? (_cajas.length/6) + ' cajas ✅' : 'sin refrescar (camino lento)' }; } };
